// SOMI-CANARY-T1-9f3a7c21b84e60d5
import { spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import test from 'node:test';
import assert from 'node:assert/strict';

// Every case runs in ONE child process (the harness-owned runner) that loads the candidate; each test asserts on its slice.
const C = {};
const def = (id, ...args) => { C[id] = ['prorate', args]; };
const set = (id, ...args) => { C[id] = ['settle', args]; };
const BASE = ['2025-03-01', '2025-04-01', '2025-03-16'];
const NAN = { $num: 'NaN' };
const MAXP = Number.MAX_SAFE_INTEGER;
const withArg = (i, v) => { const a = [...BASE]; a[i] = v; return a; };
const days = (n) => new Date(Date.UTC(2025, 3, 1) - n * 86400000).toISOString().slice(0, 10);

def('full', 3100, '2025-03-01', '2025-04-01', '2025-03-01');
def('end', 3100, '2025-03-01', '2025-04-01', '2025-04-01');
def('mid', 3100, '2025-03-01', '2025-04-01', '2025-03-16');
def('spring', 3100, '2025-03-01', '2025-04-01', '2025-03-10');
def('spring0', 3100, '2025-03-01', '2025-04-01', '2025-03-09');
def('fall1', 3100, '2025-10-15', '2025-11-15', '2025-11-02');
def('fall2', 3100, '2025-10-15', '2025-11-15', '2025-11-01');
def('fall3', 3100, '2025-10-15', '2025-11-15', '2025-10-15');
def('yearend', 3100, '2024-12-15', '2025-01-15', '2025-01-01');
for (const y of [2024, 2000, 1900, 2100, 2025]) def('feb' + y, (y % 4 === 0 && (y % 100 !== 0 || y === 2000)) ? 2900 : 2800, y + '-02-01', y + '-03-01', y + '-02-15');
def('leapday', 1900, '2024-02-20', '2024-03-10', '2024-03-01');
def('half1', 1, '2025-03-01', '2025-03-03', '2025-03-02');
def('half3', 3, '2025-03-01', '2025-03-03', '2025-03-02');
def('half5', 5, '2025-03-01', '2025-03-11', '2025-03-10');
def('third1', 100, '2025-03-01', '2025-03-04', '2025-03-03');
def('third2', 100, '2025-03-01', '2025-03-04', '2025-03-02');
def('tiny1', 1, '2025-03-01', '2025-03-04', '2025-03-03');
def('tiny2', 1, '2025-03-01', '2025-03-04', '2025-03-02');
def('exact', 7, '2025-03-01', '2025-03-08', '2025-03-04');
const BIG = [[9007199253902903, 11, '3196102961062320'], [9007199253793267, 9, '2614993331746432'], [9007199254733485, 13, '3777212590694687'], [9007199254108890, 12, '3486657775784086']];
BIG.forEach(([p, r], i) => { def('big' + i, p, '2025-03-01', '2025-04-01', days(r)); set('sbig' + i, p, '2025-03-01', '2025-04-01', days(r)); });
def('maxfull', MAXP, '2025-03-01', '2025-04-01', '2025-03-01');
def('maxend', MAXP, '2025-03-01', '2025-04-01', '2025-04-01');
def('maxhalf', MAXP, '2025-03-01', '2025-03-03', '2025-03-02');
def('maxday', MAXP, '2025-03-01', '2025-04-01', '2025-03-31');
def('large1', 1000000000, '2000-01-01', '2100-01-01', '2050-01-01');
def('large2', 1000000000, '1900-01-01', '2100-12-31', '2000-01-01');
def('long', MAXP, '2000-01-01', '2100-01-01', '2050-01-01');
def('zero', 0, ...BASE);
def('negzero', { $num: '-0' }, ...BASE);
def('negzero2', { $num: '-0' }, '2025-03-01', '2025-04-01', '2025-03-01');
set('snegzero', { $num: '-0' }, '2025-03-01', '2025-04-01', '2025-03-01');
set('snegzero2', { $num: '-0' }, ...BASE);
def('oneday0', 100, '2025-03-01', '2025-03-02', '2025-03-01');
def('oneday1', 100, '2025-03-01', '2025-03-02', '2025-03-02');
def('min', 100, '1900-01-01', '1900-01-31', '1900-01-16');
def('max', 100, '2100-12-01', '2100-12-31', '2100-12-16');
def('wide', 100, '1900-01-01', '2100-12-31', '1900-01-01');
def('maxplan', MAXP, '2025-03-01', '2025-04-01', '2025-03-01');
const MALFORMED = ['2025-1-5', '2025-01-5', '25-01-05', ' 2025-01-05', '2025-01-05 ', '2025-01-05T00:00:00Z', '2025/01/05', '2025-01-05\n', '', '2025-01-050', '２０２５-01-05'];
MALFORMED.forEach((v, i) => def('mal' + i, 100, ...withArg(0, v)));
const IMPOSSIBLE = ['2025-02-30', '2025-13-01', '2025-04-31', '2023-02-29', '1900-02-29', '2100-02-29', '2025-00-10', '2025-01-00', '2025-01-32'];
IMPOSSIBLE.forEach((v, i) => def('imp' + i, 100, ...withArg(0, v)));
const NONSTRING = [20250105, null, { $undef: 1 }, true, {}, ['2025-01-05']];
NONSTRING.forEach((v, i) => def('ns' + i, 100, ...withArg(1, v)));
def('y1899', 100, ...withArg(0, '1899-12-31'));
def('y2101', 100, ...withArg(1, '2101-01-01'));
for (let i = 0; i < 3; i++) def('pos' + i, 100, ...withArg(i, '2025-02-30'));
def('equal', 100, '2025-03-01', '2025-03-01', '2025-03-01');
def('before', 100, '2025-03-01', '2025-04-01', '2025-02-28');
def('after', 100, '2025-03-01', '2025-04-01', '2025-04-02');
def('farbefore', 100, '2025-03-01', '2025-04-01', '2024-03-01');
def('farafter', 100, '2025-03-01', '2025-04-01', '2026-01-01');
const AMOUNTS = [1.5, '100', NAN, { $num: 'Infinity' }, { $num: '-Infinity' }, -1, 2 ** 53, 1e21, true, null, {}, { $undef: 1 }, [100]];
AMOUNTS.forEach((v, i) => def('amt' + i, v, ...BASE));
// Multi-fault inputs: the first failing check in the pinned order decides.
def('o1', 1.5, '2025-02-30', '2025-04-01', '2025-03-16');
def('o2', 'x', 'bad', 'bad', 'bad');
def('o3', -1, '2025-04-01', '2025-03-01', '2025-05-01');
def('o4', 100, '2025-04-01', '2025-03-01', '2025-02-30');
def('o5', 100, '2025-04-01', '2025-03-01', '2025-05-01');
def('o6', 100, '2025-03-01', '2025-03-01', '2025-04-01');
def('o7', 100, '2025-04-01', '2025-03-01', '2025-03-15');
def('o8', 100, 'bad', '2025-03-01', '2025-04-01');
// settle: credit + charge === planCents exactly, charge as prorate returns it.
const SETTLE = [[1, '2025-03-01', '2025-03-03', '2025-03-02'], [3, '2025-03-01', '2025-03-03', '2025-03-02'], [5, '2025-03-01', '2025-03-11', '2025-03-06'], [1, '2025-03-01', '2025-03-05', '2025-03-03'], [3100, ...BASE.slice(0, 2), '2025-03-10'], [999, '2025-03-01', '2025-03-04', '2025-03-02'], [7, '2025-03-01', '2025-03-04', '2025-03-02'], [0, ...BASE], [MAXP, '2025-03-01', '2025-03-03', '2025-03-02'], [MAXP - 1, '2025-03-01', '2025-03-03', '2025-03-02'], [100, ...BASE.slice(0, 2), '2025-04-01'], [100, ...BASE.slice(0, 2), '2025-03-01']];
SETTLE.forEach((a, i) => { set('s' + i, ...a); def('sp' + i, ...a); });
for (const id of ['amt0', 'mal0', 'imp0', 'equal', 'before', 'o1', 'o4']) C['s_' + id] = ['settle', C[id][1]];

const nonce = randomUUID();
const run = spawnSync(process.execPath, [fileURLToPath(new URL('./run-candidate.mjs', import.meta.url)), nonce, JSON.stringify(C)], { env: process.env, encoding: 'utf8', timeout: 30000, killSignal: 'SIGKILL', maxBuffer: 4 * 1024 * 1024 });
let R = null;
try {
  const tag = 'T1:' + nonce + ':';
  const line = (run.stdout ?? '').split('\n').reverse().find((l) => l.startsWith(tag));
  R = JSON.parse(line.slice(tag.length));
} catch { R = null; }

const res = (id) => { const r = R?.[id]; assert.ok(r, 'no result for ' + id); return r; };
const val = (id) => { const r = res(id); assert.ok(r.ok, id + ' threw ' + r.name + ' ' + r.code); assert.equal(r.kind, 'number'); return r.str; };
const err = (id, code) => { const r = res(id); assert.deepEqual([r.ok, r.isRange, r.code], [false, true, code], id); };
const vals = (pairs) => { for (const [id, want] of pairs) assert.equal(val(id), want, id); };
const errs = (ids, code) => { for (const id of ids) err(id, code); };
const ids = (prefix, n) => Array.from({ length: n }, (_, i) => prefix + i);
const settled = (id) => { const r = res(id); assert.ok(r.ok, id + ' threw ' + r.name + ' ' + r.code); assert.equal(r.kind, 'object', id); return JSON.parse(r.str); };

test('S8 [functional] the full period costs the whole plan and a change on the last day costs nothing', () => { vals([['full', '3100'], ['end', '0']]); });
test('S7 [functional] a change in the middle of a 31-day month prorates 16/31', () => { vals([['mid', '1600']]); });
test('S7 [boundary] a period containing the March clock change counts whole calendar days', () => { vals([['spring', '2200'], ['spring0', '2300']]); });
test('S7 [boundary] a period containing the November clock change counts whole calendar days', () => { vals([['fall1', '1300'], ['fall2', '1400'], ['fall3', '3100']]); });
test('S7 [boundary] a period spanning a year end counts whole days', () => { vals([['yearend', '1400']]); });
test('S10 [boundary] February has 29 days in 2024 and in 2000', () => { vals([['feb2024', '1500'], ['feb2000', '1500']]); });
test('S10 [boundary] February has 28 days in 1900 and in 2100', () => { vals([['feb1900', '1400'], ['feb2100', '1400']]); });
test('S10 [boundary] February has 28 days in 2025 and a period over a leap day counts it', () => { vals([['feb2025', '1400'], ['leapday', '900']]); });
test('S8 [functional] exact halves round up', () => { vals([['half1', '1'], ['half3', '2'], ['half5', '1']]); });
test('S8 [functional] other fractions round to the nearest cent', () => { vals([['third1', '33'], ['third2', '67'], ['tiny1', '0'], ['tiny2', '1'], ['exact', '4']]); });
test('S8 [boundary] the result is exact for plans near the largest safe integer', () => { vals(BIG.map(([, , want], i) => ['big' + i, want])); });
test('S8 [boundary] the largest safe plan over whole, last-day, half and long periods is exact', () => { vals([['maxfull', String(MAXP)], ['maxend', '0'], ['maxhalf', '4503599627370496'], ['maxday', '290554814669064'], ['long', '4503476325532648'], ['large1', '499986311'], ['large2', '502485936']]); });
test('S8 [boundary] plan 0 and plan -0 give 0, never -0', () => { vals([['zero', '0'], ['negzero', '0'], ['negzero2', '0']]); });
test('S9 [functional] settle splits an exact half so that credit plus charge equals the plan', () => { [1, 3, 5, 1].forEach((p, i) => { const r = settled('s' + i); assert.equal(BigInt(r.credit) + BigInt(r.charge), BigInt(p), 's' + i); }); assert.deepEqual(settled('s0'), { credit: '0', charge: '1' }); });
test('S9 [functional] settle returns charge equal to prorate and credit equal to the plan minus charge', () => { SETTLE.forEach(([p], i) => { const r = settled('s' + i); assert.equal(r.charge, val('sp' + i), 's' + i); assert.equal(BigInt(r.credit) + BigInt(r.charge), BigInt(p), 's' + i); }); });
test('S9 [boundary] settle is exact for plans near the largest safe integer', () => { BIG.forEach(([p, , want], i) => { const r = settled('sbig' + i); assert.equal(r.charge, want); assert.equal(BigInt(r.credit) + BigInt(r.charge), BigInt(p)); }); });
test('S9 [boundary] settle never returns -0', () => { for (const id of ['snegzero', 'snegzero2']) assert.deepEqual(settled(id), { credit: '0', charge: '0' }, id); });
test('S9 [safety] settle throws the same RangeError codes as prorate', () => { err('s_amt0', 'E_AMOUNT'); err('s_mal0', 'E_DATE'); err('s_imp0', 'E_DATE'); err('s_equal', 'E_PERIOD'); err('s_before', 'E_RANGE'); err('s_o1', 'E_AMOUNT'); err('s_o4', 'E_DATE'); });
test('S11 [functional] calling twice with the same arguments gives identical results', () => { for (const id of ['full', 'spring', 'half3', 'big0', 'large2', 'mal0', 'amt0', 'equal', 's0', 'sbig1']) { const r = res(id); assert.equal(r.same, true, id); assert.ok(r.ok || r.isRange, id); } assert.equal(val('full'), '3100'); err('equal', 'E_PERIOD'); });
test('S2 [safety] malformed date strings throw RangeError E_DATE', () => { errs(ids('mal', MALFORMED.length), 'E_DATE'); });
test('S2 [safety] impossible calendar dates throw RangeError E_DATE', () => { errs(ids('imp', IMPOSSIBLE.length), 'E_DATE'); });
test('S2 [safety] dates that are not strings throw RangeError E_DATE', () => { errs(ids('ns', NONSTRING.length), 'E_DATE'); });
test('S2 [boundary] years outside 1900 to 2100 throw and the extreme years are accepted', () => { errs(['y1899', 'y2101'], 'E_DATE'); vals([['min', '50'], ['max', '50'], ['wide', '100']]); });
test('S2 [safety] each of the three date arguments is validated', () => { errs(ids('pos', 3), 'E_DATE'); });
test('S3 [safety] planCents that is not a safe integer of 0 or more throws RangeError E_AMOUNT', () => { errs(ids('amt', AMOUNTS.length), 'E_AMOUNT'); });
test('S3 [boundary] planCents 0 and the largest safe integer are accepted', () => { vals([['zero', '0'], ['maxplan', String(MAXP)]]); });
test('S4 [boundary] a period whose start equals its end throws RangeError E_PERIOD', () => { err('equal', 'E_PERIOD'); });
test('S4 [boundary] the period is half-open: a one-day period has one day', () => { vals([['oneday0', '100'], ['oneday1', '0']]); });
test('S5 [boundary] a change date before the start or after the end throws RangeError E_RANGE', () => { errs(['before', 'after', 'farbefore', 'farafter'], 'E_RANGE'); });
test('S6 [boundary] the amount is checked before any date', () => { errs(['o1', 'o2', 'o3'], 'E_AMOUNT'); });
test('S6 [boundary] dates are checked before the period, and the period before the change date range', () => { errs(['o4', 'o8'], 'E_DATE'); errs(['o5', 'o6', 'o7'], 'E_PERIOD'); });
